    w.WriteHeader(200) // always 200 once the process is up
}

func main() {
    ready.Store(true)
    srv := &http.Server{Addr: ":8080", Handler: mux}
    go srv.ListenAndServe()

    ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGTERM)
    defer stop()
    <-ctx.Done()

    ready.Store(false)
    // tell LB we are leaving, then shut down immediately
    srv.Shutdown(context.Background())
}
